async function run(id,fn){if(id!=='R9UL06')return;const f=await fixture((id.startsWith('R9UE')||id.startsWith('R9UI')||id.startsWith('R9UL'))?'editor':id.startsWith('R9UR')?'owner':'reviewer',{listDelay:id==='R9US01'?400:0,archiveDelay:id==='R9UR02'?1200:0});let status='pass',failure='',observation={};try{observation=await fn(f)||{};}catch(e){status='fail';failure=e.stack||String(e);}await f.page.screenshot({path:`${art}/${id}.png`,fullPage:true});writeFileSync(`${art}/${id}-body.txt`,await f.page.locator('body').innerText());await f.context.tracing.stop({path:`${art}/${id}.zip`});const result={id,status,expected:'Correct behavior, not observed-bad success',failure,observation,calls:f.calls,pageErrors:f.errors,environment:'Production Chromium153 at isolated5396, HTTPS backend mocks'};writeFileSync(`${art}/${id}.json`,JSON.stringify(result,null,2)+'\n');results.push(result);console.log(JSON.stringify({id,status,failure:failure.split('\n')[0],observation,calls:f.calls.map(c=>c.action??c.type),pageErrors:f.errors}));await f.context.close();}
await run('R9US01',async f=>{await login(f,`?shared=${shared.id}`);await f.page.getByRole('button',{name:'指定した限定版を開く',exact:true}).waitFor({state:'visible'});await f.page.waitForTimeout(900);const automaticCalls=f.calls.filter(c=>c.action==='shared_snapshot').length,titleVisible=await f.page.getByRole('heading',{name:shared.projection.title,exact:true}).isVisible(),buttonDisabled=await f.page.getByRole('button',{name:'指定した限定版を開く',exact:true}).isDisabled();writeFileSync(`${art}/R9US01-observed-before-control.json`,JSON.stringify({automaticCalls,titleVisible,buttonDisabled},null,2)+'\n');requireCondition(automaticCalls===1&&titleVisible,'Approved shared deep link must open the specified fixed edition after initial list completes');return {automaticCalls,titleVisible,buttonDisabled};});
